mapper.body:
{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": { "allow_fallbacks": true },
  "messages": [
    {
      "role": "system",
      "content": "You are a catering event coordinator assistant. Extract event details from the customer message and return ONLY a valid JSON object with these fields: event_date (string YYYY-MM-DD or descriptive like 'Saturday March 15' or null), party_size (integer or null), occasion (string describing the event type, e.g. 'birthday party', 'corporate lunch', 'wedding reception', or null), dietary_needs (string or null), budget_per_head (number or null), preferred_time (string HH:MM 24h or null), venue (string or null). Do not include any explanation or markdown."
    },
    {
      "role": "user",
      "content": "Customer message: {{1.body.messages[0].text}}"
    }
  ],
  "temperature": 0.1,
  "max_tokens": 300
}

{
  "properties": {
    "dealname": "Catering-Inquiry — {{3.occasion}} — {{1.body.actors[0].first_name}} {{1.body.actors[0].last_name}} ({{formatDate(now; 'YYYY-MM-DD'; 'America/New_York')}})",
    "pipeline": "default",
    "dealstage": "{{env.HUBSPOT_STAGE_NEW_LEAD}}",
    "deal_type": "Catering-Inquiry",
    "description": "Catering inquiry via Freshchat (Scenario AT).
Occasion: {{3.occasion}}
Event Date: {{3.event_date}}
Party Size: {{3.party_size}}
Dietary Needs: {{3.dietary_needs}}
Venue: {{3.venue}}
Preferred Time: {{3.preferred_time}}
Budget per Head: {{3.budget_per_head}}
Customer: {{1.body.actors[0].first_name}} {{1.body.actors[0].last_name}}
Email: {{1.body.actors[0].email}}
Phone: {{1.body.actors[0].phone}}
Freshchat Conversation ID: {{1.body.id}}
Original Message: {{1.body.messages[0].text}}
Received: {{formatDate(now; 'YYYY-MM-DD HH:mm:ss'; 'America/New_York')}} ET",
    "priority": "MEDIUM"
  }
}

{
  "model": "anthropic/claude-sonnet-4-6",
  "models": ["anthropic/claude-sonnet-4-6", "{{env.OPENROUTER_FALLBACK_MODEL}}"],
  "route": "fallback",
  "provider": { "allow_fallbacks": true },
  "messages": [
    {
      "role": "system",
      "content": "You are an upscale restaurant event coordinator. Write a warm, professional follow-up email body (4–6 sentences, no markdown, no subject line) to a customer who has submitted a catering inquiry. The email should: (1) thank them for their interest by name, (2) confirm the key event details you received, (3) let them know that a personalised catering menu and pricing proposal will be sent within 24 hours, (4) invite any questions they may have, (5) express excitement about their event. Keep the tone warm, professional, and celebratory."
    },
    {
      "role": "user",
      "content": "Customer first name: {{1.body.actors[0].first_name}}. Occasion: {{3.occasion}}. Event date: {{3.event_date}}. Party size: {{3.party_size}}. Dietary needs: {{3.dietary_needs}}. Venue: {{3.venue}}."
    }
  ],
  "temperature": 0.6,
  "max_tokens": 350
}

{
  "actor_type": "agent",
  "actor_id": "{{env.FRESHCHAT_BOT_ID}}",
  "message_type": "normal",
  "message_parts": [
    {
      "text": {
        "content": "Thank you for your catering inquiry, {{1.body.actors[0].first_name}}! We've received your request for {{3.occasion}} on {{3.event_date}} for {{3.party_size}} guests. A confirmation email has been sent to {{1.body.actors[0].email}} and our events team will send you a personalised catering menu and pricing within 24 hours. Feel free to reply here with any additional details!"
      }
    }
  ]
}
